import{_ as s,a0 as i,w as a,s as d,ao as p,I as l,x as n,a1 as r,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"在 Ubuntu 15.04 中如何安装和使用 Snort | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 15.04 中如何安装和使用 Snort | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 15.04 中如何安装和使用 Snort | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 15.04 中如何安装和使用 Snort | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150811 How to Install Snort and Usage in Ubuntu 15.04","title":"在 Ubuntu 15.04 中如何安装和使用 Snort","tag":"201509","desc":""},"relativePath":"201509/20150811 How to Install Snort and Usage in Ubuntu 15.04.md","filePath":"[post].md"}'),c={name:"201509/20150811 How to Install Snort and Usage in Ubuntu 15.04.md"};function u(g,t,m,b,h,f){const o=i("Link");return a(),d("div",null,[t[16]||(t[16]=p(`<h1 id="在-ubuntu-15-04-中如何安装和使用-snort" tabindex="-1">在 Ubuntu 15.04 中如何安装和使用 Snort <a class="header-anchor" href="#在-ubuntu-15-04-中如何安装和使用-snort" aria-label="Permalink to “在 Ubuntu 15.04 中如何安装和使用 Snort”">​</a></h1><p>对于网络安全而言入侵检测是一件非常重要的事。入侵检测系统（IDS）用于检测网络中非法与恶意的请求。Snort是一款知名的开源的入侵检测系统。其 Web界面（Snorby）可以用于更好地分析警告。Snort使用iptables/pf防火墙来作为入侵检测系统。本篇中，我们会安装并配置一个开源的入侵检测系统snort。</p><h3 id="snort-安装" tabindex="-1">Snort 安装 <a class="header-anchor" href="#snort-安装" aria-label="Permalink to “Snort 安装”">​</a></h3><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>snort所使用的数据采集库（DAQ）用于一个调用包捕获库的抽象层。这个在snort上就有。下载过程如下截图所示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/downloading_daq.png" alt="downloading_daq"></p><p>解压并运行./configure、make、make install来安装DAQ。然而，DAQ要求其他的工具，因此，./configure脚本会生成下面的错误。</p><p>flex和bison错误</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/flexandbison_error.png" alt="flexandbison_error"></p><p>libpcap错误</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libpcap-error.png" alt="libpcap error"></p><p>因此在安装DAQ之前先安装flex/bison和libcap。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/install_flex.png" alt="install_flex"></p><p>如下所示安装libpcap开发库</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libpcap-dev-installation.png" alt="libpcap-dev installation"></p><p>安装完必要的工具后，再次运行./configure脚本，将会显示下面的输出。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/without_error_configure.png" alt="without_error_configure"></p><p>make和make install 命令的结果如下所示。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make-install.png" alt="make install"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make.png" alt="make"></p><p>成功安装DAQ之后，我们现在安装snort。如下图使用wget下载它。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/downloading_snort.png" alt="downloading_snort"></p><p>使用下面的命令解压安装包。</p><pre><code>#tar -xvzf  snort-2.9.7.3.tar.gz
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/snort_extraction.png" alt="snort_extraction"></p><p>创建安装目录并在脚本中设置prefix参数。同样也建议启用包性能监控（PPM）的sourcefire标志。</p><pre><code>#mkdir /usr/local/snort

#./configure --prefix=/usr/local/snort/ --enable-sourcefire
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/snort_installation.png" alt="snort_installation"></p><p>配置脚本会由于缺少libpcre-dev、libdumbnet-dev 和zlib开发库而报错。</p><p>配置脚本由于缺少libpcre库报错。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/pcre-error.png" alt="pcre-error"></p><p>配置脚本由于缺少dnet（libdumbnet）库而报错。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libdnt-error.png" alt="libdnt error"></p><p>配置脚本由于缺少zlib库而报错</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/zlib-error.png" alt="zlib error"></p><p>如下所示，安装所有需要的开发库。</p><pre><code># aptitude install libpcre3-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libpcre3-dev-install.png" alt="libpcre3-dev install"></p><pre><code># aptitude install libdumbnet-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/libdumnet-dev-installation.png" alt="libdumnet-dev installation"></p><pre><code># aptitude install zlib1g-dev
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/zlibg-dev-installation.png" alt="zlibg-dev installation"></p><p>安装完snort需要的库之后，再次运行配置脚本就不会报错了。</p><p>运行make和make install命令在/usr/local/snort目录下完成安装。</p><pre><code>#make
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make-snort.png" alt="make snort"></p><pre><code>#make install
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/make-install-snort.png" alt="make install snort"></p><p>最后，从/usr/local/snort/bin中运行snort。现在它对eth0的所有流量都处在promisc模式（包转储模式）。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/snort-running.png" alt="snort running"></p><p>如下图所示snort转储流量。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/07/traffic1.png" alt="traffic"></p><h4 id="snort的规则和配置" tabindex="-1">Snort的规则和配置 <a class="header-anchor" href="#snort的规则和配置" aria-label="Permalink to “Snort的规则和配置”">​</a></h4><p>从源码安装的snort还需要设置规则和配置，因此我们需要复制规则和配置到/etc/snort下面。我们已经创建了单独的bash脚本来用于设置规则和配置。它会设置下面这些snort设置。</p><ul><li><p>在linux中创建用于snort IDS服务的snort用户。</p></li><li><p>在/etc下面创建snort的配置文件和文件夹。</p></li><li><p>权限设置并从源代码的etc目录中复制数据。</p></li><li><p>从snort文件中移除规则中的#(注释符号)。</p></li><li></li></ul><pre><code>#!/bin/bash#
# snort源代码的路径
snort_src=&quot;/home/test/Downloads/snort-2.9.7.3&quot;
echo &quot;adding group and user for snort...&quot;
groupadd snort &amp;&gt; /dev/null
useradd snort -r -s /sbin/nologin -d /var/log/snort -c snort_idps -g snort &amp;&gt; /dev/null#snort configuration
echo &quot;Configuring snort...&quot;mkdir -p /etc/snort
mkdir -p /etc/snort/rules
touch /etc/snort/rules/black_list.rules
touch /etc/snort/rules/white_list.rules
touch /etc/snort/rules/local.rules
mkdir /etc/snort/preproc_rules
mkdir /var/log/snort
mkdir -p /usr/local/lib/snort_dynamicrules
chmod -R 775 /etc/snort
chmod -R 775 /var/log/snort
chmod -R 775 /usr/local/lib/snort_dynamicrules
chown -R snort:snort /etc/snort
chown -R snort:snort /var/log/snort
chown -R snort:snort /usr/local/lib/snort_dynamicrules
###copy  configuration and rules from  etc directory under source code of snort
echo &quot;copying from snort source to /etc/snort .....&quot;
echo $snort_src
echo &quot;-------------&quot;
cp $snort_src/etc/*.conf* /etc/snort
cp $snort_src/etc/*.map /etc/snort##enable rules
sed -i &#39;s/include \\$RULE\\_PATH/#include \\$RULE\\_PATH/&#39; /etc/snort/snort.conf
echo &quot;---DONE---&quot;
</code></pre><p>改变脚本中的snort源目录路径并运行。下面是成功的输出。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/running_script.png" alt="running script"></p><p>上面的脚本从snort源中复制下面的文件和文件夹到/etc/snort配置文件中</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/created.png" alt="files copied"></p><p>snort的配置非常复杂，要让IDS能正常工作需要进行下面必要的修改。</p><pre><code>ipvar HOME_NET 192.168.1.0/24  # LAN side
</code></pre><hr><pre><code>ipvar EXTERNAL_NET !$HOME_NET   # WAN side
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/12.png" alt="veriable set"></p><pre><code>var RULE_PATH /etc/snort/rules     # snort signature path
var SO_RULE_PATH /etc/snort/so_rules        #rules in shared libraries
var PREPROC_RULE_PATH /etc/snort/preproc_rules  # Preproces path
var WHITE_LIST_PATH /etc/snort/rules        # dont scan
var BLACK_LIST_PATH /etc/snort/rules        #  Must scan
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/rule-path.png" alt="main path"></p><pre><code>include $RULE_PATH/local.rules   # file for custom rules
</code></pre><p>移除ftp.rules、exploit.rules前面的注释符号(#)。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/path-rules.png" alt="path rules"></p>`,70)),l("p",null,[t[1]||(t[1]=n("现在",-1)),r(o,{href:"https://www.snort.org/downloads/community/community-rules.tar.gz"},{default:e(()=>[...t[0]||(t[0]=[n("下载社区规则",-1)])]),_:1}),t[2]||(t[2]=n("并解压到/etc/snort/rules。启用snort.conf中的社区及紧急威胁规则。",-1))]),t[17]||(t[17]=p(`<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/wget_rules.png" alt="wget_rules"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/community-rules1.png" alt="community rules"></p><p>进行了上面的更改后，运行下面的命令来检验配置文件。</p><pre><code>#snort -T -c /etc/snort/snort.conf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/08/snort-final.png" alt="snort running"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>本篇中，我们关注了开源IDPS系统snort在Ubuntu上的安装和配置。通常它用于监控事件，然而它可以被配置成用于网络保护的在线模式。snort规则可以在离线模式中可以使用pcap捕获文件进行测试和分析</p><hr>`,8)),l("p",null,[t[4]||(t[4]=n("via: ",-1)),r(o,{href:"http://linoxide.com/security/install-snort-usage-ubuntu-15-04/"},{default:e(()=>[...t[3]||(t[3]=[n("http://linoxide.com/security/install-snort-usage-ubuntu-15-04/",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=n("作者：",-1)),r(o,{href:"http://linoxide.com/author/naveeda/"},{default:e(()=>[...t[5]||(t[5]=[n("nido",-1)])]),_:1}),t[9]||(t[9]=n(" 译者：",-1)),r(o,{href:"https://github.com/geekpi"},{default:e(()=>[...t[6]||(t[6]=[n("geekpi",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=n("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原创翻译，",-1)),r(o,{href:"https://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[n("Linux中国",-1)])]),_:1}),t[15]||(t[15]=n(" 荣誉推出",-1))])])}const T=s(c,[["render",u]]);export{w as __pageData,T as default};
